#include <iostream>
#include <memory>
#include <string>

struct Node
{
    std::string action;
    std::unique_ptr<Node> next;
    Node(std::string a) : action(a) {}
};

int main()
{
    std::unique_ptr<Node> head;
    for (std::string a : {"build", "move", "jump"}) {
        auto n = std::make_unique<Node>(a);
        n->next = std::move(head);
        head = std::move(n);
    }

    for (const Node* n = head.get(); n; n = n->next.get())
        std::cout << n->action << " ";
    std::cout << "\n";

    std::cout << "undo " << head->action << "\n";
    head = std::move(head->next);              // pop: the old head is deleted
    std::cout << "top is now " << head->action << "\n";
    return 0;                                  // the rest of the chain cleans itself up
}

