exercises.solution:
#include <memory>
#include <string>

struct Node
{
    inline static int alive = 0;
    std::string action;
    std::unique_ptr<Node> next;
    Node(std::string action) : action(action) { alive++; }
    ~Node() { alive--; }
};

class UndoStack
{
public:
    UndoStack() = default;
    ~UndoStack() { while (head) head = std::move(head->next); }   // one node at a time, no deep recursion
    UndoStack(const UndoStack&) = delete;
    UndoStack& operator=(const UndoStack&) = delete;

    void push(const std::string& action)
    {
        auto n = std::make_unique<Node>(action);
        n->next = std::move(head);   // the new node owns the old chain
        head = std::move(n);
        count++;
    }
    std::string pop()
    {
        if (!head) return "";
        std::string a = head->action;
        head = std::move(head->next);   // the old top is deleted here
        count--;
        return a;
    }
    std::string peek() const { return head ? head->action : ""; }
    int size() const { return count; }
    bool empty() const { return !head; }
private:
    std::unique_ptr<Node> head;
    int count = 0;
};

