exercises.solution:
#include <memory>
#include <string>

struct QNode
{
    inline static int alive = 0;
    std::string name;
    std::unique_ptr<QNode> next;
    QNode(std::string name) : name(name) { alive++; }
    ~QNode() { alive--; }
};

class PatientQueue
{
public:
    PatientQueue() = default;
    ~PatientQueue() { while (head) head = std::move(head->next); }
    PatientQueue(const PatientQueue&) = delete;
    PatientQueue& operator=(const PatientQueue&) = delete;

    void join(const std::string& name)
    {
        auto n = std::make_unique<QNode>(name);
        QNode* raw = n.get();              // remember it before moving the owner away
        if (tail) tail->next = std::move(n);
        else head = std::move(n);          // empty queue: the new node is the front too
        tail = raw;
        count++;
    }
    std::string next()
    {
        if (!head) return "";
        std::string name = head->name;
        head = std::move(head->next);      // the served node is deleted
        if (!head) tail = nullptr;         // empty again: tail must not dangle
        count--;
        return name;
    }
    std::string front() const { return head ? head->name : ""; }
    int size() const { return count; }
private:
    std::unique_ptr<QNode> head;   // owns the chain
    QNode* tail = nullptr;         // just points at the last node
    int count = 0;
};

exercises.prompt:
Route (a linked list of Waypoints) can already pushFront, size and list. Add:
- bool contains(const std::string& name) const;
- int indexOf(const std::string& name) const: the position of the first match counting from 0 at the front, or -1;
- bool remove(const std::string& name): unlinks and deletes the first waypoint with that name, returns true, or false if there is none. It must work for the first, a middle and the last waypoint, and size() must stay right.

