#include <memory>
#include <string>

struct Waypoint
{
    inline static int alive = 0;
    std::string name;
    std::unique_ptr<Waypoint> next;
    Waypoint(std::string name) : name(name) { alive++; }
    ~Waypoint() { alive--; }
};

class Route
{
public:
    void pushFront(const std::string& name)
    {
        auto w = std::make_unique<Waypoint>(name);
        w->next = std::move(head);
        head = std::move(w);
        count++;
    }
    int size() const { return count; }
    std::string list() const
    {
        std::string out;
        for (const Waypoint* w = head.get(); w; w = w->next.get())
            out += (out.empty() ? "" : " > ") + w->name;
        return out;
    }

    bool contains(const std::string& name) const { return indexOf(name) != -1; }
    int indexOf(const std::string& name) const
    {
        int i = 0;
        for (const Waypoint* w = head.get(); w; w = w->next.get(), i++)
            if (w->name == name) return i;
        return -1;
    }
    bool remove(const std::string& name)
    {
        // link points at whichever unique_ptr owns the current waypoint (head, or a next)
        std::unique_ptr<Waypoint>* link = &head;
        while (*link) {
            if ((*link)->name == name) {
                *link = std::move((*link)->next);   // skip over it; it is deleted
                count--;
                return true;
            }
            link = &(*link)->next;
        }
        return false;
    }
private:
    std::unique_ptr<Waypoint> head;
    int count = 0;
};
